describe('identity plugin test kit', () => {
  it('reports manifest, security and protocol contract checks', async () => {
    await expect(verifyIdentityPluginContract(manifest, passingProbe)).resolves.toMatchObject({ pluginId: manifest.id, checks: expect.arrayContaining(['tenantIsolation', 'protocol']) });
  });
  it('fails closed when a required security probe fails', async () => {
    await expect(verifyIdentityPluginContract(manifest, { ...passingProbe, validateSecretLeakage: () => Promise.resolve(false) })).rejects.toBeInstanceOf(PluginContractError);
  });
  it('rejects incomplete manifests', async () => {
    await expect(verifyIdentityPluginContract({ ...manifest, apiVersion: 'v1' }, passingProbe)).rejects.toMatchObject({ check: 'apiVersion' });
  });
